// ofxManifold — 3D map geometry conformance runner (round 3A-4).
//
// Reads tests/vectors/levels.vec, generated by tests/ref/reference_levels.py.
//
// Beyond matching the reference, every set of weights is checked for the
// properties that make it a 3D map, computed here from the C++ alone:
//   - they sum to one and none is negative;
//   - they REPRODUCE the point: sum of weight x (x_i, y_i, height of node i on
//     that level) is the point -- (x, y) from the floor plan, and z exactly.

#include "../src/core/ofxManifold2D.h"
#include "../src/core/ofxManifoldLevels.h"
#include "../src/mapping/ofxManifoldMap3D.h"
#include "../src/io/ofxManifoldSerialize3D.h"

#include <glm/vec3.hpp>

#include <cmath>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <map>
#include <sstream>
#include <string>
#include <vector>

using namespace ofxManifold;

namespace {

struct Tally { int pass = 0; int fail = 0; };
std::map<std::string, Tally> tallies;
std::vector<std::string> failures;
const float tolerance = 1e-5f;

void record(const std::string& cls, const std::string& name, bool ok,
            const std::string& detail) {
    Tally& t = tallies[cls];
    if (ok) ++t.pass; else {
        ++t.fail;
        failures.push_back(cls + "  " + name + "\n      " + detail);
    }
    std::cout << (ok ? "  pass  " : "  FAIL  ")
              << std::left << std::setw(10) << cls << name << "\n";
}

bool close(float a, float b) { return std::fabs(a - b) <= tolerance; }

void expectKeyword(std::istringstream& in, const char* kw) {
    std::string tok; in >> tok;
    if (tok != kw) {
        std::cerr << "malformed vector: expected " << kw << ", got " << tok
                  << "\n";
        std::exit(2);
    }
}

std::vector<std::string> splitOn(const std::string& s, char c) {
    std::vector<std::string> v;
    std::string cur;
    for (char ch : s) {
        if (ch == c) { v.push_back(cur); cur.clear(); } else cur += ch;
    }
    v.push_back(cur);
    return v;
}

struct Plan {
    std::vector<glm::vec2> pos;
    std::vector<std::vector<NodeID>> tris;
};

struct Stack {
    std::string plan;
    Levels levels;
};

std::map<std::string, Plan> plans;
std::map<std::string, Stack> stacks;

// "n@l=w ..." or "OUTSIDE"
bool readExpect(std::istringstream& in,
                std::map<std::pair<NodeID, LevelID>, float>& w) {
    std::string tok;
    bool inside = true;
    while (in >> tok) {
        if (tok == "OUTSIDE") { inside = false; continue; }
        const std::size_t at = tok.find('@'), eq = tok.find('=');
        w[{static_cast<NodeID>(std::stoul(tok.substr(0, at))),
           static_cast<LevelID>(std::stoul(tok.substr(at + 1, eq - at - 1)))}] =
            std::stof(tok.substr(eq + 1));
    }
    return inside;
}

// Compare, then check the 3D-map properties against the point (px, py, z).
bool check(const Evaluation3D& e, bool wantInside,
           const std::map<std::pair<NodeID, LevelID>, float>& want,
           const Levels& lv, const Plan& plan, float px, float py, float z,
           bool zIgnored, std::ostringstream& d) {
    if (e.inside != wantInside) {
        d << (e.inside ? "inside, expected outside" : "outside, expected inside");
        return false;
    }
    if (!wantInside) {
        if (!e.weights.empty()) { d << "outside but weights given"; return false; }
        return true;
    }
    // A weight within the tolerance of zero IS zero. On a region's edge the
    // floor plan's weight for the node across it is zero in exact arithmetic,
    // but with fused multiply-add -- every arm64 Mac -- it comes out as
    // +-1e-10. Levels passes it through, multiplied; it is neither a weight
    // that matters nor a negative one. Found by CI on macOS arm64, then
    // reproduced here with -ffp-contract=fast.
    std::map<std::pair<NodeID, LevelID>, float> got;
    for (const auto& lw : e.weights) {
        if (lw.weight < -tolerance) {
            d << "negative weight " << lw.weight << " on " << lw.node << "@"
              << lw.level;
            return false;
        }
        if (std::fabs(lw.weight) > tolerance) {
            got[{lw.node, lw.level}] += lw.weight;
        }
    }
    if (got.size() != want.size()) {
        d << got.size() << " weights, expected " << want.size();
        return false;
    }
    for (const auto& kv : want) {
        auto it = got.find(kv.first);
        if (it == got.end() || !close(it->second, kv.second)) {
            d << kv.first.first << "@" << kv.first.second << ": expected "
              << kv.second << ", got "
              << (it == got.end() ? 0.0f : it->second);
            return false;
        }
    }
    float sum = 0.0f;
    glm::vec3 p(0.0f);
    for (const auto& kv : got) {
        sum += kv.second;
        const glm::vec2 q = plan.pos[kv.first.first];
        p += kv.second * glm::vec3(q.x, q.y,
                                   lv.height(kv.first.second, kv.first.first));
    }
    if (!close(sum, 1.0f)) { d << "weights sum to " << sum; return false; }
    if (!close(p.x, px) || !close(p.y, py) || (!zIgnored && !close(p.z, z))) {
        d << "weights reproduce (" << p.x << ", " << p.y << ", " << p.z
          << "), not the point (" << px << ", " << py << ", " << z << ")";
        return false;
    }
    return true;
}

Manifold2D buildFloor(const Plan& plan) {
    Manifold2D m;
    for (std::size_t i = 0; i < plan.pos.size(); ++i) {
        m.addNode("n" + std::to_string(i), plan.pos[i]);
    }
    for (const auto& t : plan.tris) m.addRegion(t);
    return m;
}

std::map<std::string, Manifold2D> floors;
std::map<std::string, Map3D> maps3;

bool slurp(const std::string& file, std::string& out) {
    std::ifstream f("tests/fixtures/" + file);
    if (!f) return false;
    std::stringstream ss; ss << f.rdbuf();
    out = ss.str();
    return true;
}

int fileVersion(const std::string& text) {
    const std::size_t p = text.find("\"version\": ");
    return p == std::string::npos ? -1 : std::atoi(text.c_str() + p + 11);
}

bool sameDense(const std::vector<float>& got, const std::vector<float>& want,
               const char* what, std::ostringstream& d);

// Two 3D maps hold the same thing: levels, every height, the value set, every
// value, and the same channels on every level and halfway between each pair.
bool sameMap3(const Map3D& a, const Map3D& b, std::size_t nodes,
              std::ostringstream& d) {
    if (a.count() != b.count()) {
        d << a.count() << " levels, expected " << b.count();
        return false;
    }
    for (LevelID k = 0; k < a.count(); ++k) {
        if (!close(a.levels().base(k), b.levels().base(k))) {
            d << "level " << k << " starts at " << a.levels().base(k);
            return false;
        }
        for (NodeID n = 0; n < nodes; ++n) {
            if (!close(a.levels().height(k, n), b.levels().height(k, n))) {
                d << "node " << n << " on level " << k << " at "
                  << a.levels().height(k, n) << ", expected "
                  << b.levels().height(k, n);
                return false;
            }
        }
    }
    // Every level holds the room's outputs: the same names, channels and
    // trims on each. A level missing one reads the same until something is
    // bound to it there -- then the binding is dropped (round 3A-6, found by
    // a gate on version 1 files).
    for (LevelID k = 0; k < a.count(); ++k) {
        const Mapping& x = a.level(k);
        const Mapping& y = b.level(k);
        if (x.targetCount() != y.targetCount()) {
            d << "level " << k << " has " << x.targetCount()
              << " outputs, expected " << y.targetCount();
            return false;
        }
        for (TargetID t = 0; t < x.targetCount(); ++t) {
            if (x.targetName(t) != y.targetName(t)
                || x.targetChannel(t) != y.targetChannel(t)
                || !close(x.targetTrim(t), y.targetTrim(t))) {
                d << "output " << t << " on level " << k << " is "
                  << x.targetName(t) << ", expected " << y.targetName(t);
                return false;
            }
        }
    }
    if (a.valueSet().size() != b.valueSet().size()) {
        d << a.valueSet().size() << " values declared, expected "
          << b.valueSet().size();
        return false;
    }
    for (std::size_t v = 0; v < a.valueSet().size(); ++v) {
        const ValueDef& x = a.valueSet()[v];
        const ValueDef& y = b.valueSet()[v];
        if (x.name != y.name || !close(x.fallback, y.fallback)
            || !close(x.lo, y.lo) || !close(x.hi, y.hi)) {
            d << "value " << v << " is " << x.name << ", expected " << y.name;
            return false;
        }
        for (LevelID k = 0; k < a.count(); ++k) {
            for (NodeID n = 0; n < nodes; ++n) {
                if (!close(a.value(k, n, v), b.value(k, n, v))) {
                    d << x.name << " of node " << n << " on level " << k
                      << " is " << a.value(k, n, v) << ", expected "
                      << b.value(k, n, v);
                    return false;
                }
            }
        }
    }
    auto probe = [&](LevelID k, float t) {
        Evaluation3D e;
        e.inside = true;
        for (NodeID n = 0; n < nodes; ++n) {
            const float w = 1.0f / static_cast<float>(nodes);
            if (t < 1.0f) e.weights.push_back(LevelWeight{n, k, w * (1.0f - t)});
            if (t > 0.0f) e.weights.push_back(LevelWeight{n, k + 1, w * t});
        }
        return e;
    };
    for (LevelID k = 0; k < a.count(); ++k) {
        for (float t : {0.0f, 0.5f}) {
            if (t > 0.0f && k + 1 >= a.count()) continue;
            const Evaluation3D e = probe(k, t);
            std::ostringstream dd;
            if (!sameDense(a.toChannelLevels(e), b.toChannelLevels(e),
                           "levels", dd)
                || !close(a.silenceShare(e), b.silenceShare(e))) {
                d << "on level " << k << (t > 0 ? " and above" : "") << ": "
                  << dd.str();
                return false;
            }
        }
    }
    return true;
}

std::vector<float> readFloatsUntil(std::istringstream& in, const char* stop) {
    std::vector<float> v;
    std::string tok;
    while (in >> tok && tok != stop) v.push_back(std::stof(tok));
    return v;
}

// "n@l=w ..." until the given keyword; "OUTSIDE" gives an outside evaluation.
Evaluation3D readW3(std::istringstream& in, const char* stop) {
    Evaluation3D e;
    e.inside = true;
    std::string tok;
    while (in >> tok && tok != stop) {
        if (tok == "OUTSIDE") { e.inside = false; continue; }
        const std::size_t at = tok.find('@'), eq = tok.find('=');
        e.weights.push_back(LevelWeight{
            static_cast<NodeID>(std::stoul(tok.substr(0, at))),
            static_cast<LevelID>(std::stoul(tok.substr(at + 1, eq - at - 1))),
            std::stof(tok.substr(eq + 1))});
    }
    return e;
}

bool sameDense(const std::vector<float>& got, const std::vector<float>& want,
               const char* what, std::ostringstream& d) {
    if (got.size() != want.size()) {
        d << what << ": " << got.size() << " channels, expected " << want.size();
        return false;
    }
    for (std::size_t i = 0; i < want.size(); ++i) {
        if (!close(got[i], want[i])) {
            d << what << " channel " << i << ": expected " << want[i]
              << ", got " << got[i];
            return false;
        }
    }
    return true;
}

// The two things every reading of a Map3D is checked for, beyond matching:
// every level agrees about the room, and weights on ONE level read exactly
// as that level's own Mapping reads them.
bool map3Properties(const Map3D& m, const Evaluation3D& e,
                    std::ostringstream& d) {
    std::vector<const Mapping*> all;
    for (LevelID k = 0; k < m.count(); ++k) all.push_back(&m.level(k));
    const auto dis = checkAgreement(all);
    if (!dis.empty()) {
        d << "levels disagree about the room: " << dis[0].message;
        return false;
    }
    if (!e.inside || e.weights.empty()) return true;
    const LevelID k = e.weights[0].level;
    WeightVector w;
    for (const auto& lw : e.weights) {
        if (lw.level != k) return true;
        w.push_back(WeightedNode{lw.node, lw.weight});
    }
    return sameDense(m.toChannels(e), m.level(k).toChannels(w),
                     "one level vs its own Mapping", d)
        && sameDense(m.toChannelLevels(e), m.level(k).toChannelLevels(w),
                     "one level vs its own Mapping, levels", d)
        && (close(m.silenceShare(e), m.level(k).silenceShare(w))
            || (d << "silence differs from the level's own", false));
}

} // namespace

int main(int argc, char** argv) {
    const std::string path = argc > 1 ? argv[1] : "tests/vectors/levels.vec";
    std::ifstream f(path);
    if (!f) { std::cerr << "cannot open " << path << "\n"; return 2; }

    std::string line;
    while (std::getline(f, line)) {
        if (line.empty() || line[0] == '#') continue;
        std::istringstream in(line);
        std::string kind; in >> kind;

        if (kind == "NODES") {
            std::string name, tok; in >> name;
            Plan& p = plans[name];
            while (in >> tok) {
                const std::size_t c = tok.find(':'), k = tok.find(',');
                p.pos.emplace_back(std::stof(tok.substr(c + 1, k - c - 1)),
                                   std::stof(tok.substr(k + 1)));
            }
            continue;
        }
        if (kind == "TRIS") {
            std::string name, tok; in >> name;
            while (in >> tok) {
                std::vector<NodeID> t;
                for (const auto& s : splitOn(tok, ',')) {
                    t.push_back(static_cast<NodeID>(std::stoul(s)));
                }
                plans[name].tris.push_back(t);
            }
            floors[name] = buildFloor(plans[name]);
            continue;
        }
        if (kind == "STACK") {
            // Each operation must give exactly the result written after it.
            std::string name, pn; in >> name;
            expectKeyword(in, "NODES");
            in >> pn;
            expectKeyword(in, "OPS");
            std::string rest; std::getline(in, rest);
            Stack st; st.plan = pn;
            const std::size_t nodes = plans[pn].pos.size();
            for (std::string op : splitOn(rest, ';')) {
                std::istringstream o(op);
                std::string verb; if (!(o >> verb)) continue;
                std::string want, got;
                if (verb == "COPY") {
                    LevelID from; float base; o >> from >> base >> want;
                    std::vector<NodeID> blocked;
                    const LevelID at =
                        st.levels.copyLevel(from, base, nodes, &blocked);
                    if (at < st.levels.count() && blocked.empty()
                        && st.levels.base(at) == base) {
                        got = "=" + std::to_string(at);
                    } else {
                        got = "=REFUSED:";
                        if (blocked.empty()) got += "-";
                        for (std::size_t i = 0; i < blocked.size(); ++i) {
                            got += (i ? "," : "") + std::to_string(blocked[i]);
                        }
                    }
                } else if (verb == "RAISE") {
                    LevelID k; float dz; std::string ns;
                    o >> k >> dz >> ns >> want;
                    std::vector<NodeID> ids;
                    for (const auto& s : splitOn(ns, ',')) {
                        ids.push_back(static_cast<NodeID>(std::stoul(s)));
                    }
                    std::vector<NodeID> blocked;
                    if (st.levels.raise(k, ids, dz, &blocked)) got = "=OK";
                    else {
                        got = "=REFUSED:";
                        for (std::size_t i = 0; i < blocked.size(); ++i) {
                            got += (i ? "," : "") + std::to_string(blocked[i]);
                        }
                    }
                } else if (verb == "SET") {
                    LevelID k; NodeID n; float h; o >> k >> n >> h >> want;
                    got = st.levels.setHeight(k, n, h) ? "=OK" : "=REFUSED";
                } else if (verb == "MOVE") {
                    LevelID k; float dz; o >> k >> dz >> want;
                    std::vector<NodeID> blocked;
                    if (st.levels.moveLevel(k, dz, nodes, &blocked)) got = "=OK";
                    else {
                        got = "=REFUSED:";
                        if (blocked.empty()) got += "-";
                        for (std::size_t i = 0; i < blocked.size(); ++i) {
                            got += (i ? "," : "") + std::to_string(blocked[i]);
                        }
                    }
                } else if (verb == "ROOM") {
                    LevelID k; o >> k >> want;
                    // Compared as numbers: a gap is a difference of heights,
                    // float here and double in the reference.
                    const auto r = st.levels.room(k, nodes);
                    const std::vector<std::string> pair =
                        splitOn(want.substr(1), ',');
                    auto same = [](float v, const std::string& w) {
                        if (w == "inf") return std::isinf(v);
                        return !std::isinf(v)
                            && std::fabs(v - std::stof(w)) < 1e-5f;
                    };
                    got = (pair.size() == 2 && same(r.first, pair[0])
                           && same(r.second, pair[1]))
                        ? want : "=" + std::to_string(r.first) + ","
                                 + std::to_string(r.second);
                } else if (verb == "REMOVE") {
                    LevelID k; o >> k >> want;
                    got = st.levels.removeLevel(k) ? "=OK" : "=REFUSED";
                }
                if (got != want) {
                    record("ANALYTIC", "stack_" + name + "_" + verb, false,
                           "'" + op + "' gave " + got);
                }
            }
            stacks[name] = st;
            continue;
        }

        if (kind == "MAP3") {
            // Built by operations, each that can refuse giving the result
            // written after it.
            std::string name, pn; in >> name;
            expectKeyword(in, "NODES");
            in >> pn;
            expectKeyword(in, "OPS");
            std::string rest; std::getline(in, rest);
            Map3D m;
            const std::size_t nodes = plans[pn].pos.size();
            auto target = [&](const std::string& nm) {
                return m.level(0).findTarget(nm);
            };
            for (const std::string& op : splitOn(rest, ';')) {
                std::istringstream o(op);
                std::vector<std::string> w;
                std::string tok;
                while (o >> tok) w.push_back(tok);
                if (w.empty()) continue;
                std::string want, got;
                if (w.back()[0] == '=') { want = w.back(); w.pop_back(); }
                const std::string& v = w[0];
                if (v == "OUT") {
                    m.addOutput(w[1], std::stoi(w[2]), std::stof(w[3]));
                } else if (v == "AFTER" || v == "TAP") {
                    const SumMode mode = w[4] == "power" ? SumMode::PowerPreserving
                                                         : SumMode::Linear;
                    if (v == "AFTER") {
                        std::vector<std::pair<TargetID, float>> srcs;
                        for (const auto& sv : splitOn(w[5], ',')) {
                            const auto kv = splitOn(sv, ':');
                            srcs.emplace_back(target(kv[0]), std::stof(kv[1]));
                        }
                        m.addDerivedFromOutputs(w[1], std::stoi(w[2]),
                                                std::stof(w[3]), mode, srcs);
                    } else {
                        std::vector<std::pair<NodeID, float>> srcs;
                        for (const auto& sv : splitOn(w[5], ',')) {
                            const auto kv = splitOn(sv, ':');
                            srcs.emplace_back(
                                static_cast<NodeID>(std::stoul(kv[0])),
                                std::stof(kv[1]));
                        }
                        m.addDerived(w[1], std::stoi(w[2]), std::stof(w[3]),
                                     mode, srcs);
                    }
                } else if (v == "COPY") {
                    std::vector<NodeID> blocked;
                    const LevelID at = m.copyLevel(
                        std::stoul(w[1]), std::stof(w[2]), nodes, &blocked);
                    if (at < m.count()) got = "=" + std::to_string(at);
                    else {
                        got = "=REFUSED:";
                        if (blocked.empty()) got += "-";
                        for (std::size_t i = 0; i < blocked.size(); ++i) {
                            got += (i ? "," : "") + std::to_string(blocked[i]);
                        }
                    }
                } else if (v == "RAISE") {
                    std::vector<NodeID> ids;
                    for (const auto& sv : splitOn(w[3], ',')) {
                        ids.push_back(static_cast<NodeID>(std::stoul(sv)));
                    }
                    std::vector<NodeID> blocked;
                    if (m.raise(std::stoul(w[1]), ids, std::stof(w[2]),
                                &blocked)) {
                        got = "=OK";
                    } else {
                        got = "=REFUSED:";
                        for (std::size_t i = 0; i < blocked.size(); ++i) {
                            got += (i ? "," : "") + std::to_string(blocked[i]);
                        }
                    }
                } else if (v == "BIND") {
                    m.bind(std::stoul(w[1]), std::stoul(w[2]), target(w[3]),
                           std::stof(w[4]));
                } else if (v == "SILENCE") {
                    m.bindSilence(std::stoul(w[1]), std::stoul(w[2]),
                                  std::stof(w[3]));
                } else if (v == "CLEAR") {
                    m.clearBindings(std::stoul(w[1]), std::stoul(w[2]));
                } else if (v == "FRACTION") {
                    got = m.setOutputFraction(std::stoul(w[1]), std::stoul(w[2]),
                                              std::stof(w[3]))
                        ? "=OK" : "=REFUSED";
                } else if (v == "VALUE") {
                    const std::size_t i = m.addValue(w[1], std::stof(w[2]),
                                                     std::stof(w[3]),
                                                     std::stof(w[4]));
                    got = i == static_cast<std::size_t>(-1)
                        ? "=REFUSED" : "=" + std::to_string(i);
                } else if (v == "SETH") {
                    got = m.setHeight(std::stoul(w[1]), std::stoul(w[2]),
                                      std::stof(w[3])) ? "=OK" : "=REFUSED";
                } else if (v == "SETV") {
                    m.setValue(std::stoul(w[1]), std::stoul(w[2]),
                               m.findValue(w[3]), std::stof(w[4]));
                } else if (v == "REMOVEOUT") {
                    m.removeOutput(target(w[1]));
                } else if (v == "TRIM") {
                    m.setTrim(target(w[1]), std::stof(w[2]));
                } else if (v == "REMOVELEVEL") {
                    got = m.removeLevel(std::stoul(w[1])) ? "=OK" : "=REFUSED";
                } else if (v == "USERIG") {
                    // The rig is another map's room, as an editor saves it.
                    std::vector<std::string> refused;
                    if (m.useRig(rigOf(maps3[w[1]].level(0)), &refused)) {
                        got = "=OK";
                    } else {
                        got = "=REFUSED:";
                        for (std::size_t i = 0; i < refused.size(); ++i) {
                            got += (i ? "," : "") + refused[i];
                        }
                    }
                } else if (v == "REMAP") {
                    std::vector<NodeID> table;
                    for (const auto& sv : splitOn(w[1], ',')) {
                        const long x = std::stol(sv);
                        table.push_back(x < 0 ? InvalidNode
                                              : static_cast<NodeID>(x));
                    }
                    m.remapNodes(table);
                } else {
                    std::cerr << "unknown op " << v << "\n";
                    return 2;
                }
                if (got != want) {
                    record("ANALYTIC", "map3_" + name + "_" + v, false,
                           "'" + op + "' gave '" + got + "', expected '"
                           + want + "'");
                }
            }
            maps3[name] = m;
            continue;
        }

        std::string name, cls; in >> name >> cls;
        std::ostringstream d;

        if (kind == "HEIGHTS") {
            // Every node's height on every level, and the level count.
            std::string sn; in >> sn;
            const Levels& lv = stacks[sn].levels;
            std::vector<std::vector<float>> want;
            std::string tok;
            while (in >> tok) {
                if (tok[0] == 'L') { want.emplace_back(); continue; }
                for (const auto& s : splitOn(tok, ',')) {
                    want.back().push_back(std::stof(s));
                }
            }
            bool ok = lv.count() == want.size();
            if (!ok) d << lv.count() << " levels, expected " << want.size();
            for (LevelID k = 0; ok && k < want.size(); ++k) {
                for (NodeID i = 0; ok && i < want[k].size(); ++i) {
                    if (!close(lv.height(k, i), want[k][i])) {
                        ok = false;
                        d << "node " << i << " on level " << k << " at "
                          << lv.height(k, i) << ", expected " << want[k][i];
                    }
                }
            }
            record(cls, name, ok, d.str());

        } else if (kind == "EVAL3") {
            std::string sn; in >> sn;
            expectKeyword(in, "W");
            Evaluation floor;
            floor.inside = true;
            std::string tok;
            while (in >> tok && tok != "Z") {
                const std::size_t eq = tok.find('=');
                floor.weights.push_back(WeightedNode{
                    static_cast<NodeID>(std::stoul(tok.substr(0, eq))),
                    std::stof(tok.substr(eq + 1))});
            }
            float z; in >> z;
            expectKeyword(in, "EXPECT");
            std::map<std::pair<NodeID, LevelID>, float> want;
            const bool inside = readExpect(in, want);
            const Stack& st = stacks[sn];
            const Plan& plan = plans[st.plan];
            float px = 0.0f, py = 0.0f;
            for (const auto& wn : floor.weights) {
                px += wn.weight * plan.pos[wn.id].x;
                py += wn.weight * plan.pos[wn.id].y;
            }
            const Evaluation3D e = st.levels.evaluate(floor, z);
            const bool ok = check(e, inside, want, st.levels, plan, px, py, z,
                                  st.levels.count() == 1, d);
            record(cls, name, ok, d.str());

        } else if (kind == "EVALXYZ") {
            // The whole path: the C++ floor plan evaluates (x, y) itself.
            std::string sn, fp; in >> sn >> fp;
            expectKeyword(in, "P");
            float x, y, z; in >> x >> y >> z;
            expectKeyword(in, "EXPECT");
            std::map<std::pair<NodeID, LevelID>, float> want;
            const bool inside = readExpect(in, want);
            const std::string plan = fp == "SQUARE" ? "square" : fp;
            const Stack& st = stacks[sn];
            const Evaluation floor = floors[plan].evaluate(glm::vec2(x, y));
            const Evaluation3D e = st.levels.evaluate(floor, z);
            const bool ok = check(e, inside, want, st.levels, plans[plan],
                                  x, y, z, st.levels.count() == 1, d);
            record(cls, name, ok, d.str());

        } else if (kind == "CONT") {
            // No step along a straight sweep may change any weight by more
            // than the bound; every step must be inside and reproduce its
            // point.
            std::string sn, fp; in >> sn >> fp;
            const std::string plan = fp == "SQUARE" ? "square" : fp;
            expectKeyword(in, "FROM");
            float ax, ay, az; in >> ax >> ay >> az;
            expectKeyword(in, "TO");
            float bx, by, bz; in >> bx >> by >> bz;
            expectKeyword(in, "STEPS");
            int steps; in >> steps;
            expectKeyword(in, "MAXSTEP");
            float bound; in >> bound;
            const Stack& st = stacks[sn];
            std::map<std::pair<NodeID, LevelID>, float> prev;
            float worst = 0.0f;
            bool ok = true;
            for (int s = 0; ok && s <= steps; ++s) {
                const float u = static_cast<float>(s) / steps;
                const float x = ax + (bx - ax) * u, y = ay + (by - ay) * u;
                const float z = az + (bz - az) * u;
                const Evaluation3D e = st.levels.evaluate(
                    floors[plan].evaluate(glm::vec2(x, y)), z);
                std::map<std::pair<NodeID, LevelID>, float> now;
                // Weights within the tolerance of zero are dropped, as
                // check() drops them: on the square's diagonal the floor plan
                // reports the node across the edge at 0, or +-1e-10 with
                // fused multiply-add.
                for (const auto& lw : e.weights) {
                    if (std::fabs(lw.weight) > tolerance) {
                        now[{lw.node, lw.level}] += lw.weight;
                    }
                }
                std::ostringstream dd;
                if (!check(e, true, now, st.levels, plans[plan], x, y, z,
                           false, dd)) {
                    ok = false; d << "step " << s << ": " << dd.str();
                    break;
                }
                if (s > 0) {
                    auto keys = now;
                    for (const auto& kv : prev) keys[kv.first];
                    for (const auto& kv : keys) {
                        const float a = prev.count(kv.first) ? prev[kv.first] : 0.0f;
                        const float b = now.count(kv.first) ? now[kv.first] : 0.0f;
                        worst = std::max(worst, std::fabs(b - a));
                    }
                }
                prev = now;
            }
            if (ok && worst > bound) {
                ok = false;
                d << "a step changed a weight by " << worst << ", bound "
                  << bound;
            }
            record(cls, name, ok, d.str());

        } else if (kind == "NEWNODE") {
            // A node the levels have never heard of: each level's start.
            std::string sn; in >> sn;
            expectKeyword(in, "NODE");
            NodeID n; in >> n;
            expectKeyword(in, "HEIGHTS");
            std::string hs; in >> hs;
            const auto want = splitOn(hs, ',');
            const Levels& lv = stacks[sn].levels;
            bool ok = lv.count() == want.size();
            for (LevelID k = 0; ok && k < want.size(); ++k) {
                if (!close(lv.height(k, n), std::stof(want[k]))
                    || lv.bent(k, n)) {
                    ok = false; d << "level " << k << ": " << lv.height(k, n);
                }
            }
            record(cls, name, ok, d.str());

        } else if (kind == "REMAP3") {
            std::string sn; in >> sn;
            expectKeyword(in, "TABLE");
            std::vector<NodeID> table;
            std::string tok;
            while (in >> tok && tok[0] != 'L') {
                const long v = std::stol(tok);
                table.push_back(v < 0 ? InvalidNode : static_cast<NodeID>(v));
            }
            Levels lv = stacks[sn].levels;
            lv.remapNodes(table);
            std::vector<std::vector<float>> want(1);
            while (in >> tok) {
                if (tok[0] == 'L') { want.emplace_back(); continue; }
                for (const auto& s : splitOn(tok, ',')) {
                    want.back().push_back(std::stof(s));
                }
            }
            bool ok = lv.count() == want.size();
            if (!ok) d << lv.count() << " levels";
            for (LevelID k = 0; ok && k < want.size(); ++k) {
                for (NodeID i = 0; ok && i < want[k].size(); ++i) {
                    if (!close(lv.height(k, i), want[k][i])) {
                        ok = false;
                        d << "node " << i << " on level " << k << " at "
                          << lv.height(k, i) << ", expected " << want[k][i];
                    }
                }
            }
            record(cls, name, ok, d.str());

        } else if (kind == "CH3" || kind == "CH3XYZ") {
            std::string mn; in >> mn;
            const Map3D& m = maps3[mn];
            Evaluation3D e;
            if (kind == "CH3") {
                expectKeyword(in, "W");
                e = readW3(in, "ROUTED");
            } else {
                std::string fp; in >> fp;
                expectKeyword(in, "P");
                float x, y, z; in >> x >> y >> z;
                expectKeyword(in, "ROUTED");
                e = m.levels().evaluate(floors["square"].evaluate({x, y}), z);
            }
            const std::vector<float> routed = readFloatsUntil(in, "SILENCE");
            float sil; in >> sil;
            expectKeyword(in, "LEVELS");
            std::vector<float> levels;
            std::string tok;
            while (in >> tok) levels.push_back(std::stof(tok));
            bool ok = sameDense(m.toChannels(e), routed, "routed", d)
                   && sameDense(m.toChannelLevels(e), levels, "levels", d);
            if (ok && !close(m.silenceShare(e), sil)) {
                ok = false; d << "silence " << m.silenceShare(e)
                              << ", expected " << sil;
            }
            if (ok) ok = map3Properties(m, e, d);
            record(cls, name, ok, d.str());

        } else if (kind == "FILE3") {
            // A pair written by the reference loads, equals the map built by
            // operations, and save -> load -> save is byte-stable.
            std::string mf, of, as, mn;
            in >> mf >> of >> as >> mn;
            std::string mt, ot;
            bool ok = slurp(mf, mt) && slurp(of, ot);
            if (!ok) d << "missing " << mf << " or " << of;
            Manifold2D fl;
            Map3D got;
            if (ok) {
                const io::LoadResult r = io::loadMap3D(mt, ot, fl, got);
                ok = r.ok;
                if (!ok) d << "refused: " << r.error;
            }
            if (ok) ok = sameMap3(got, maps3[mn], fl.nodeCount(), d);
            if (ok) {
                const std::string s1 = io::saveManifold3D(fl, got);
                const std::string s2 = io::saveMapping3D(got, fl);
                Manifold2D fl2; Map3D again;
                const io::LoadResult r2 = io::loadMap3D(s1, s2, fl2, again);
                ok = r2.ok && io::saveManifold3D(fl2, again) == s1
                          && io::saveMapping3D(again, fl2) == s2;
                if (!ok) d << "save -> load -> save is not byte-stable"
                           << (r2.ok ? "" : ": " + r2.error);
            }
            record(cls, name, ok, d.str());

        } else if (kind == "SAVE3") {
            // The map built by operations, saved by the C++ as the versions
            // given, reloaded equal. PLAIN: byte-identical to the 2D savers.
            std::string mn, mv, ov;
            in >> mn;
            expectKeyword(in, "MAPV");
            in >> mv;
            expectKeyword(in, "OUTV");
            in >> ov;
            const Map3D& m = maps3[mn];
            const Manifold2D& fl = floors["square"];
            const std::string s1 = io::saveManifold3D(fl, m);
            const std::string s2 = io::saveMapping3D(m, fl);
            bool ok = true;
            if (mv == "PLAIN") {
                ok = s1 == io::saveManifold(fl) && s2 == io::saveMapping(m.level(0), fl);
                if (!ok) d << "a flat map with no values does not save as a 2D map";
            } else if (fileVersion(s1) != std::stoi(mv)
                       || fileVersion(s2) != std::stoi(ov)) {
                ok = false;
                d << "saved as versions " << fileVersion(s1) << " and "
                  << fileVersion(s2) << ", expected " << mv << " and " << ov;
            }
            Manifold2D fl2; Map3D back;
            if (ok) {
                const io::LoadResult r = io::loadMap3D(s1, s2, fl2, back);
                ok = r.ok;
                if (!ok) d << "its own files refused: " << r.error;
            }
            if (ok) ok = sameMap3(back, m, fl.nodeCount(), d);
            record(cls, name, ok, d.str());

        } else if (kind == "REFUSE3") {
            std::string mf, of; in >> mf >> of;
            std::string reason, tok;
            while (in >> tok) reason += (reason.empty() ? "" : " ") + tok;
            std::string mt, ot;
            bool ok = slurp(mf, mt) && slurp(of, ot);
            if (!ok) d << "missing " << mf << " or " << of;
            Manifold2D fl = floors["square"];
            Map3D got;
            got.addOutput("untouched", 42, 1.0f);
            if (ok) {
                const io::LoadResult r = io::loadMap3D(mt, ot, fl, got);
                ok = !r.ok && r.error.find(reason) != std::string::npos;
                if (r.ok) d << "loaded";
                else if (!ok) d << "refused for the wrong reason: " << r.error;
                // and nothing was half-written into the caller's objects
                if (ok && (got.level(0).findTarget("untouched") == InvalidTarget
                           || fl.nodeCount() != plans["square"].pos.size())) {
                    ok = false; d << "a refused load changed its outputs";
                }
            }
            record(cls, name, ok, d.str());

        } else if (kind == "REFUSE2D") {
            std::string which, file, reason; in >> which >> file >> reason;
            std::string text;
            bool ok = slurp(file, text);
            if (ok) {
                io::LoadResult r;
                if (which == "MAP") {
                    Manifold2D fl; r = io::loadManifold(text, fl);
                } else {
                    Mapping mp; r = io::loadMapping(text, floors["square"], mp);
                }
                ok = !r.ok && r.error.find(reason) != std::string::npos;
                if (!ok) d << (r.ok ? "loaded" : "wrong reason: " + r.error);
            }
            record(cls, name, ok, d.str());

        } else if (kind == "VAL3") {
            std::string mn; in >> mn;
            expectKeyword(in, "W");
            const Evaluation3D e = readW3(in, "VALUE");
            std::string vn; in >> vn;
            expectKeyword(in, "EXPECT");
            float want; in >> want;
            const Map3D& m = maps3[mn];
            const float got = m.valueAt(m.findValue(vn), e);
            const bool ok = close(got, want);
            if (!ok) d << vn << " = " << got << ", expected " << want;
            record(cls, name, ok, d.str());

        } else {
            std::cerr << "unknown record type: " << kind << "\n";
            return 2;
        }
    }

    int fail = 0, pass = 0;
    for (const auto& kv : tallies) { pass += kv.second.pass; fail += kv.second.fail; }
    if (!failures.empty()) {
        std::cout << "\nfailures:\n";
        for (const auto& s : failures) std::cout << "  " << s << "\n";
    }
    std::cout << "\n" << pass << "/" << (pass + fail) << "  "
              << (fail ? "RED" : "GREEN") << "\n";
    return fail ? 1 : 0;
}
